87	        $data = $this->safeWithStorePayload($data, (string) ($row->professional_id ?? ''), $subdomain);
88	        $data = $this->safeApplyBrandImageFallbacks($data, $subdomain);
89	
90	        Cache::put($key, $data, $this->jitteredPayloadTtl());
91	
92	        return $data;
93	    }
