95	    /**
96	     * Returns the public_payload TTL with ±20% jitter applied.
97	     *
98	     * Mirrors CacheLockService::writeWithJitter's distribution so payload-cache
99	     * writes (which use raw Cache::put inside our manual single-flight) get the
100	     * same expiry-spreading behaviour as rememberLocked-managed entries.
101	     */
102	    private function jitteredPayloadTtl(): int
103	    {
104	        return (int) round((int) config('partna.cache.ttls.public_payload') * (0.8 + mt_rand(0, 4000) / 10000.0));
105	    }
