107	    /**
108	     * Get public site payload (MOST CRITICAL - 95% of traffic)
109	     *
110	     * IMPORTANT: This must match the PublicSiteController response shape exactly.
111	     */
112	    public function getPublicSitePayload(string $subdomain): ?array
113	    {
114	        $subdomain = strtolower($subdomain);
115	
116	        $key = CacheKeyGenerator::publicSitePayload($subdomain);
117	        $cached = Cache::get($key);
118	
119	        if ($cached === self::MISS_SENTINEL) {
120	            return null;
121	        }
122	        if (is_array($cached)) {
123	            // Backward-compatible cache healing for payload shape changes.
124	            // Older cache entries may not include `services`.
125	            if (array_key_exists('services', $cached)) {
126	                $cached = $this->ensureBlockCollections($cached);
127	                $cached = $this->ensureProfessionalType(
128	                    $cached,
129	                    (string) data_get($cached, 'professional.id', '')
130	                );
131	                $cached = $this->safeWithStorePayload(
132	                    $cached,
133	                    (string) data_get($cached, 'professional.id', ''),
134	                    $subdomain
135	                );
136	
137	                if (! array_key_exists('legal', $cached)) {
138	                    $cached['legal'] = null;
139	                }
140	
141	                // Always resolve image variant paths to URLs (handles pre-URL-resolution cache entries)
142	                $site = $cached['site'] ?? null;
143	                if (is_array($site)) {
144	                    $professionalId = (string) data_get($cached, 'professional.id', '');
145	                    $cached['site'] = $this->safeHydrateSitePayload(
146	                        $site,
147	                        $professionalId,
148	                        '',
149	                        $subdomain
150	                    );
151	                }
152	
153	                Cache::put($key, $cached, $this->jitteredPayloadTtl());
154	
155	                return $cached;
156	            }
157	            Cache::forget($key);
158	        }
159	
160	        // Cache miss — acquire a per-subdomain fill lock so only one process rebuilds
161	        // the payload from the DB view while concurrent requests wait (single-flight).
162	        $fillLock = Cache::lock('site:fill:'.$subdomain, 10);
163	
164	        try {
165	            // Block up to 5 s for the lock; raises LockTimeoutException if it can't.
166	            $fillLock->block(5);
167	        } catch (\Illuminate\Contracts\Cache\LockTimeoutException) {
168	            // Another process is (or was) filling the cache.
169	            $warm = Cache::get($key);
170	            if ($warm === self::MISS_SENTINEL) {
171	                return null;
172	            }
173	            if (is_array($warm)) {
174	                return $warm;
175	            }
176	
177	            // Cache still empty — compute directly rather than flash-404.
178	            // Bounded stampede risk: only requests in the lock-timeout window run this path.
179	            return $this->buildPayloadFromDb($subdomain, $key);
180	        }
181	
182	        try {
183	            // Double-check: the lock winner may have filled the cache while we waited.
184	            $rechecked = Cache::get($key);
185	            if ($rechecked === self::MISS_SENTINEL) {
186	                return null;
187	            }
188	            if (is_array($rechecked) && array_key_exists('services', $rechecked)) {
189	                return $rechecked;
190	            }
191	
192	            return $this->buildPayloadFromDb($subdomain, $key);
193	        } finally {
194	            $fillLock->release();
195	        }
196	    }
