198	    /**
199	     * @param  array<string, mixed>  $payload
200	     * @return array<string, mixed>
201	     */
202	    private function applyBrandImageFallbacks(array $payload): array
203	    {
204	        $professional = $payload['professional'] ?? null;
205	        if (! is_array($professional) || ($professional['professional_type'] ?? null) === 'brand') {
206	            return $payload;
207	        }
208	
209	        $affiliateId = (string) ($professional['id'] ?? '');
210	        if (empty($affiliateId)) {
211	            return $payload;
212	        }
213	
214	        // JSON column is affiliate-controlled; use it only as a hint for which brand is configured.
215	        $brandPartner = $payload['site']['settings']['brand_partner'] ?? null;
216	        if (! is_array($brandPartner) || empty($brandPartner['professional_id'])) {
217	            return $payload;
218	        }
219	
220	        $claimedBrandId = (string) $brandPartner['professional_id'];
221	
222	        // BrandPartnerLink is the consent record — verify before using any brand data.
223	        $link = BrandPartnerLink::where('affiliate_professional_id', $affiliateId)
224	            ->where('brand_professional_id', $claimedBrandId)
225	            ->first();
226	
227	        if (! $link) {
228	            Log::warning('Brand-partner enrichment skipped: no verified link in consent table.', [
229	                'affiliate_id' => $affiliateId,
230	                'brand_id' => $claimedBrandId,
231	            ]);
232	
233	            return $payload;
234	        }
235	
236	        // Resolve brand_id from the verified link record, never from the mutable JSON.
237	        $brandId = (string) $link->brand_professional_id;
238	        $brandSite = Site::query()
239	            ->where('professional_id', $brandId)
240	            ->first();
241	
242	        if (! $brandSite) {
243	            return $payload;
244	        }
245	
246	        // Brand placeholders now live in site_media (pool=design, purpose=placeholder).
247	        // The service resolves variant URLs; we project them to { url, alt_text }
248	        // to match the new Hydrogen brand-design response shape.
249	        $designMedia = app(\App\Services\Media\BrandDesignMediaService::class)
250	            ->listDesignMedia((string) $brandSite->id);
251	
252	        if (empty($designMedia['placeholders'])) {
253	            return $payload;
254	        }
255	
256	        $placeholderImages = array_map(
257	            fn (array $p) => [
258	                'url' => $p['url'],
259	                'alt_text' => $p['alt_text'],
260	            ],
261	            $designMedia['placeholders']
262	        );
263	
264	        $imageKeys = ['gallery', 'content_images'];
265	
266	        foreach ($imageKeys as $key) {
267	            if (! isset($payload['site'][$key]) || ! is_array($payload['site'][$key])) {
268	                continue;
269	            }
270	
271	            if (empty($payload['site'][$key])) {
272	                $payload['site'][$key] = $placeholderImages;
273	            }
274	        }
275	
276	        return $payload;
277	    }
