363	     * @return array<string, mixed>
364	     */
365	    public function enrichSiteWithBrandPartnerRadius(array $site): array
366	    {
367	        $settings = is_array($site['settings'] ?? null) ? $site['settings'] : [];
368	        $brandPartner = is_array($settings['brand_partner'] ?? null)
369	            ? $settings['brand_partner']
370	            : (is_array($settings['brandPartner'] ?? null) ? $settings['brandPartner'] : []);
371	
372	        $professionalId = $brandPartner['professional_id'] ?? $brandPartner['professionalId'] ?? null;
373	        if (! is_string($professionalId) || trim($professionalId) === '') {
374	            return $site;
375	        }
376	
377	        $enrichment = $this->resolveBrandPartnerEnrichmentData(trim($professionalId));
378	        if (! is_array($enrichment)) {
379	            return $site;
380	        }
381	
382	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_radius', 'borderRadius') && $this->isFilledString($enrichment['border_radius'] ?? null)) {
383	            $brandPartner['border_radius'] = $enrichment['border_radius'];
384	        }
385	        if ($this->isMissingBrandPartnerField($brandPartner, 'font_file_url', 'fontFileUrl') && $this->isFilledString($enrichment['font_file_url'] ?? null)) {
386	            $brandPartner['font_file_url'] = $enrichment['font_file_url'];
387	        }
388	        if ($this->isMissingBrandPartnerField($brandPartner, 'username', 'handle') && $this->isFilledString($enrichment['username'] ?? null)) {
389	            $brandPartner['username'] = $enrichment['username'];
390	        }
391	        if ($this->isMissingBrandPartnerField($brandPartner, 'first_name', 'firstName') && $this->isFilledString($enrichment['first_name'] ?? null)) {
392	            $brandPartner['first_name'] = $enrichment['first_name'];
393	        }
394	        if ($this->isMissingBrandPartnerField($brandPartner, 'last_name', 'lastName') && $this->isFilledString($enrichment['last_name'] ?? null)) {
395	            $brandPartner['last_name'] = $enrichment['last_name'];
396	        }
397	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_color', 'borderColor') && $this->isFilledString($enrichment['border_color'] ?? null)) {
398	            $brandPartner['border_color'] = $enrichment['border_color'];
399	        }
400	        if ($this->isMissingBrandPartnerField($brandPartner, 'logo_letter_spacing', 'logoLetterSpacing') && $this->isFilledString($enrichment['logo_letter_spacing'] ?? null)) {
401	            $brandPartner['logo_letter_spacing'] = $enrichment['logo_letter_spacing'];
402	        }
403	        if ($this->isMissingBrandPartnerField($brandPartner, 'logo_font_size', 'logoFontSize') && $this->isFilledString($enrichment['logo_font_size'] ?? null)) {
404	            $brandPartner['logo_font_size'] = $enrichment['logo_font_size'];
405	        }
406	        if ($this->isMissingBrandPartnerField($brandPartner, 'border_width', 'borderWidth') && $this->isFilledString($enrichment['border_width'] ?? null)) {
407	            $brandPartner['border_width'] = $enrichment['border_width'];
408	        }
409	        if ($this->isMissingBrandPartnerField($brandPartner, 'general_spacing_padding', 'generalSpacingPadding') && $this->isFilledString($enrichment['general_spacing_padding'] ?? null)) {
410	            $brandPartner['general_spacing_padding'] = $enrichment['general_spacing_padding'];
411	        }
412	
413	        $settings['brand_partner'] = $brandPartner;
414	        $site['settings'] = $settings;
415	
416	        return $site;
417	    }
