419	    /**
420	     * @return array<string, string|null>|null
421	     */
422	    private function resolveBrandPartnerEnrichmentData(string $professionalId): ?array
423	    {
424	        if (array_key_exists($professionalId, $this->brandPartnerEnrichmentCache)) {
425	            return $this->brandPartnerEnrichmentCache[$professionalId];
426	        }
427	
428	        $partnerSite = Site::query()
429	            ->where('professional_id', $professionalId)
430	            ->first(['settings']);
431	
432	        $partnerProfessional = Professional::query()
433	            ->whereKey($professionalId)
434	            ->first(['handle', 'first_name', 'last_name']);
435	
436	        if (! $partnerSite && ! $partnerProfessional) {
437	            $this->brandPartnerEnrichmentCache[$professionalId] = null;
438	
439	            return null;
440	        }
441	
442	        $partnerSettings = is_array($partnerSite?->settings ?? null) ? $partnerSite->settings : [];
443	        $design = is_array($partnerSettings['design'] ?? null) ? $partnerSettings['design'] : [];
444	        $typography = is_array($design['typography'] ?? null) ? $design['typography'] : [];
445	        $resolved = [
446	            'username' => $this->normalizeString($partnerProfessional?->handle ?? null),
447	            'first_name' => $this->normalizeString($partnerProfessional?->first_name ?? null),
448	            'last_name' => $this->normalizeString($partnerProfessional?->last_name ?? null),
449	            'border_color' => $this->normalizeString($design['border_color'] ?? $design['borderColor'] ?? null),
450	            'border_radius' => $this->normalizeString($design['border_radius'] ?? $design['borderRadius'] ?? null),
451	            'border_width' => $this->normalizeString($design['border_width'] ?? $design['borderWidth'] ?? null),
452	            'general_spacing_padding' => $this->normalizeString($design['general_spacing_padding'] ?? $design['generalSpacingPadding'] ?? null),
453	            'font_file_url' => null,
454	            'logo_letter_spacing' => $this->normalizeString($typography['logo_letter_spacing'] ?? $typography['logoLetterSpacing'] ?? null),
455	            'logo_font_size' => $this->normalizeString($typography['logo_font_size'] ?? $typography['logoFontSize'] ?? null),
456	        ];
457	
458	        $this->brandPartnerEnrichmentCache[$professionalId] = $resolved;
459	
460	        return $resolved;
461	    }
