490	     * @return array<string, mixed>
491	     */
492	    private function ensureBlockCollections(array $payload): array
493	    {
494	        $links = is_array($payload['links'] ?? null) ? array_values($payload['links']) : [];
495	        $sections = is_array($payload['sections'] ?? null) ? array_values($payload['sections']) : [];
496	        $existingBlocks = is_array($payload['blocks'] ?? null) ? array_values($payload['blocks']) : [];
497	
498	        if ($links === [] && $existingBlocks !== []) {
499	            $links = array_values(array_filter($existingBlocks, function ($block): bool {
500	                return is_array($block)
501	                    && strtolower((string) ($block['block_group'] ?? '')) === 'links';
502	            }));
503	        }
504	
505	        if ($sections === [] && $existingBlocks !== []) {
506	            $sections = array_values(array_filter($existingBlocks, function ($block): bool {
507	                return is_array($block)
508	                    && strtolower((string) ($block['block_group'] ?? '')) === 'sections';
509	            }));
510	        }
511	
512	        $payload['links'] = $links;
513	        $payload['sections'] = $sections;
514	        $payload['blocks'] = $this->buildCombinedBlocksPayload($links, $sections, $existingBlocks);
515	
516	        return $payload;
