556	    /**
557	     * @param  array<int, mixed>  $links
558	     * @param  array<int, mixed>  $sections
559	     * @param  array<int, mixed>  $existingBlocks
560	     * @return array<int, array<string, mixed>>
561	     */
562	    private function buildCombinedBlocksPayload(array $links, array $sections, array $existingBlocks = []): array
563	    {
564	        if ($links === [] && $sections === []) {
565	            return array_values(array_filter($existingBlocks, fn ($block): bool => is_array($block)));
566	        }
567	
568	        $normalizedLinks = array_map(function ($block): array {
569	            $data = is_array($block) ? $block : [];
570	            $data['block_group'] = 'links';
571	
572	            return $data;
573	        }, $links);
574	
575	        $normalizedSections = array_map(function ($block): array {
576	            $data = is_array($block) ? $block : [];
577	            $data['block_group'] = 'sections';
578	
579	            return $data;
580	        }, $sections);
581	
582	        $combined = array_merge($normalizedLinks, $normalizedSections);
583	
584	        usort($combined, function (array $a, array $b): int {
585	            $aSort = (int) ($a['sort_order'] ?? PHP_INT_MAX);
586	            $bSort = (int) ($b['sort_order'] ?? PHP_INT_MAX);
587	            if ($aSort !== $bSort) {
588	                return $aSort <=> $bSort;
589	            }
590	
591	            $aId = (string) ($a['id'] ?? '');
592	            $bId = (string) ($b['id'] ?? '');
593	
594	            return $aId <=> $bId;
595	        });
596	
597	        return array_values($combined);
598	    }
