659	    /**
660	     * Resolve image variant paths to public URLs in the site payload.
661	     * The view returns storage paths; we need full URLs for the frontend.
662	     * Also resolves video variant/stream/poster paths in gallery_videos and content_videos.
663	     *
664	     * @param  array<string, mixed>  $site
665	     * @return array<string, mixed>
666	     */
667	    private function resolveImageVariantUrlsInSite(array $site, string $siteId): array
668	    {
669	        // --- Collect all media IDs (images + videos) in one pass ---
670	        $allMediaIds = [];
671	        foreach (['gallery', 'content_images', 'gallery_videos', 'content_videos'] as $key) {
672	            foreach ($site[$key] ?? [] as $item) {
673	                if (is_array($item) && ! empty($item['id'])) {
674	                    $allMediaIds[] = $item['id'];
675	                }
676	            }
677	        }
678	
679	        // Single query: one DB round-trip for all variant rows across all media types.
680	        // Index as: media_id → artifact_type → variant_key → URL
681	        $mvByMedia = [];
682	        if ($allMediaIds !== []) {
683	            $allVariants = MediaVariant::query()
684	                ->whereIn('media_id', array_unique($allMediaIds))
685	                ->get();
686	
687	            foreach ($allVariants as $mv) {
688	                $mvByMedia[$mv->media_id][$mv->artifact_type][$mv->variant_key] = $mv->url;
689	            }
690	        }
691	
692	        // --- Images: resolve variant URLs ---
693	        foreach (['gallery', 'content_images'] as $key) {
694	            $items = $site[$key] ?? [];
695	            if (! is_array($items)) {
696	                continue;
697	            }
698	            foreach ($items as $i => $item) {
699	                if (! is_array($item) || empty($item['id'])) {
700	                    continue;
701	                }
702	                $mediaId = $item['id'];
703	                $pathVariants = $item['variants'] ?? [];
704	                if (! is_array($pathVariants)) {
705	                    continue;
706	                }
707	                $urlVariants = [];
708	                foreach ($pathVariants as $variantKey => $path) {
709	                    $url = $mvByMedia[$mediaId]['webp'][$variantKey] ?? null;
710	                    if ($url !== null) {
711	                        $urlVariants[$variantKey] = $url;
712	                    }
713	                }
714	                $site[$key][$i]['variants'] = $urlVariants;
715	            }
716	
717	            usort($site[$key], function ($a, $b) {
718	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
719	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
720	                if ($aSort !== $bSort) {
721	                    return $aSort <=> $bSort;
722	                }
723	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
724	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
725	
726	                return $aId <=> $bId;
727	            });
728	        }
729	
730	        // --- Videos: resolve variant/stream/poster URLs ---
731	        foreach (['gallery_videos', 'content_videos'] as $key) {
732	            $items = $site[$key] ?? [];
733	            if (! is_array($items)) {
734	                continue;
735	            }
736	            foreach ($items as $i => $item) {
737	                if (! is_array($item) || empty($item['id'])) {
738	                    continue;
739	                }
740	                $mediaId = $item['id'];
741	                $byType = $mvByMedia[$mediaId] ?? [];
742	
743	                $site[$key][$i]['variants'] = $byType['mp4'] ?? [];
744	                $site[$key][$i]['streams'] = $byType['hls_playlist'] ?? [];
745	                $site[$key][$i]['poster'] = ($byType['poster']['poster'] ?? null);
746	            }
747	
748	            usort($site[$key], function ($a, $b) {
749	                $aSort = is_array($a) ? (int) ($a['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
750	                $bSort = is_array($b) ? (int) ($b['sort_order'] ?? PHP_INT_MAX) : PHP_INT_MAX;
751	                if ($aSort !== $bSort) {
752	                    return $aSort <=> $bSort;
753	                }
754	                $aId = is_array($a) ? (string) ($a['id'] ?? '') : '';
755	                $bId = is_array($b) ? (string) ($b['id'] ?? '') : '';
756	
757	                return $aId <=> $bId;
758	            });
759	        }
760	
761	        // Ensure video keys always exist even when there are no videos (backward-compat).
762	        $site['gallery_videos'] = $site['gallery_videos'] ?? [];
763	        $site['content_videos'] = $site['content_videos'] ?? [];
764	
765	        // --- Document: resolve preview_url from storage path to full CDN URL ---
766	        if (isset($site['document']) && is_array($site['document']) && ! empty($site['document']['preview_url'])) {
767	            $rawPath = (string) $site['document']['preview_url'];
768	            $site['document']['preview_url'] = Storage::disk(config('partna.media_disk'))->url($rawPath);
769	        }
770	
771	        return $site;
