801	    public function invalidateSite(Site $site): void
802	    {
803	        $professionalId = (string) ($site->professional_id ?? '');
804	
805	        $keys = [
806	            CacheKeyGenerator::publicSitePayload($site->subdomain),
807	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'links')),
808	            ...self::bustWithStale(CacheKeyGenerator::siteBlocks($site->id, 'sections')),
809	            CacheKeyGenerator::siteImages($site->id),
810	        ];
811	
812	        // CACHE-1: every (pool, media_type) variant of /api/images. The polling
813	        // path (?ids[]) uses unbounded fingerprint keys and relies on its own 5s
814	        // TTL — not enumerated here.
815	        foreach (CacheKeyGenerator::siteImagesViewVariants() as [$pool, $mediaType]) {
816	            $variantKey = CacheKeyGenerator::siteImagesView($site->id, $pool, $mediaType);
817	            $keys[] = $variantKey;
818	            $keys[] = $variantKey.':stale';
819	        }
820	
821	        // The auth-path Professional model cache (AUTH-1) holds the site relation
822	        // preloaded — site writes must bust it or the next 60s of authenticated
823	        // requests would see a stale subdomain / settings on $pro->site.
824	        if ($professionalId !== '') {
825	            $modelKey = CacheKeyGenerator::professionalModel($professionalId);
826	            $keys[] = $modelKey;
827	            $keys[] = $modelKey.':stale';
828	        }
829	
830	        // If subdomain changed, kill the OLD cache key too.
831	        // This is critical so old URLs redirect (via alias) instead of returning cached payload.
832	        if ($site->wasChanged('subdomain')) {
833	            $old = strtolower((string) $site->getOriginal('subdomain'));
834	            if ($old !== '') {
835	                $keys[] = CacheKeyGenerator::publicSitePayload($old);
836	            }
837	        }
838	
839	        // Invalidate all alias cache keys (your Site model has no aliases() relation)
840	        $aliasSubdomains = SiteSubdomainAlias::query()
841	            ->where('site_id', $site->id)
842	            ->pluck('subdomain')
843	            ->all();
844	
845	        foreach ($aliasSubdomains as $aliasSubdomain) {
846	            $keys[] = CacheKeyGenerator::publicSitePayload(strtolower($aliasSubdomain));
847	        }
848	
849	        if ($professionalId !== '') {
850	            $connectedProfessionalIds = BrandPartnerLink::query()
851	                ->where('brand_professional_id', $professionalId)
852	                ->pluck('affiliate_professional_id')
853	                ->all();
854	
855	            $connectedSubdomains = Site::query()
856	                ->whereIn('professional_id', $connectedProfessionalIds)
857	                ->pluck('subdomain')
858	                ->filter(fn ($subdomain): bool => is_string($subdomain) && trim($subdomain) !== '')
859	                ->map(fn ($subdomain): string => strtolower((string) $subdomain))
860	                ->all();
861	
862	            foreach ($connectedSubdomains as $connectedSubdomain) {
863	                $keys[] = CacheKeyGenerator::publicSitePayload($connectedSubdomain);
864	            }
865	        }
866	
867	        Cache::deleteMultiple(array_values(array_unique($keys)));
868	    }
