870	    public function getSiteLinkBlocks(string $siteId): array
871	    {
872	        // Single-flight + ±20% jitter + SWR via CacheLockService. Without the
873	        // lock, a cold cache after a flush lets every concurrent visitor on a
874	        // popular site rebuild this list in parallel; with int TTL the helper
875	        // also spreads expiry across the fleet.
876	        return $this->cacheLock->rememberLocked(
877	            CacheKeyGenerator::siteBlocks($siteId, 'links'),
878	            (int) config('partna.cache.ttls.public_payload'),
879	            fn () => Block::query()
880	                ->where('site_id', $siteId)
881	                ->where('block_group', 'links')
882	                ->active()
883	                ->orderBy('sort_order')
884	                ->get()
885	                ->toArray()
886	        );
887	    }
