15	
16	afterEach(function () {
17	    M::close();
18	});
19	
20	// Helpers ─────────────────────────────────────────────────────────────────────
21	
22	/**
23	 * Minimal payload array that passes the cache healing checks in getPublicSitePayload
24	 * (must contain a 'services' key so the backward-compat branch returns early).
25	 *
26	 * @return array<string, mixed>
27	 */
28	function minimalCachedPayload(): array
29	{
30	    return [
31	        'published' => true,
32	        'services' => [],
33	        'links' => [],
34	        'sections' => [],
35	        'blocks' => [],
36	        'site' => null,
37	        'professional' => null,
38	        'theme' => null,
39	        'legal' => null,
40	        'store' => null,
41	        'selected_products' => [],
42	        'default_commission_rate' => 15.0,
43	        'max_featured_products' => 12,
44	        'checkout_mode' => 'shopify',
45	    ];
46	}
47	
48	// Tests ───────────────────────────────────────────────────────────────────────
49	
50	it('returns null on lock timeout when MISS_SENTINEL is already cached', function () {
51	    $subdomain = 'test-sentinel';
52	    $key = CacheKeyGenerator::publicSitePayload($subdomain);
53	
54	    $lock = M::mock(Lock::class);
55	    $lock->shouldReceive('block')->with(5)->once()->andThrow(new LockTimeoutException);
56	
57	    // Initial miss → attempt lock → timeout → re-check returns sentinel.
58	    Cache::shouldReceive('get')->with($key)->twice()->andReturn(null, '__MISS__');
59	    Cache::shouldReceive('lock')->with('site:fill:'.$subdomain, 10)->once()->andReturn($lock);
60	
61	    $result = $this->service->getPublicSitePayload($subdomain);
62	
63	    expect($result)->toBeNull();
64	});
65	
66	it('returns cached payload on lock timeout when cache fills during the wait', function () {
67	    $subdomain = 'test-warm';
68	    $key = CacheKeyGenerator::publicSitePayload($subdomain);
69	    $payload = minimalCachedPayload();
70	
71	    $lock = M::mock(Lock::class);
72	    $lock->shouldReceive('block')->with(5)->once()->andThrow(new LockTimeoutException);
73	
74	    // Initial miss → attempt lock → timeout → re-check finds the warm payload.
75	    Cache::shouldReceive('get')->with($key)->twice()->andReturn(null, $payload);
76	    Cache::shouldReceive('lock')->with('site:fill:'.$subdomain, 10)->once()->andReturn($lock);
77	
78	    $result = $this->service->getPublicSitePayload($subdomain);
79	
80	    expect($result)->toBe($payload);
81	});
82	
83	it('falls through to compute on lock timeout when cache is still empty (CACHE-4 fix)', function () {
84	    // Verifies the fix: rather than returning null immediately when the lock times
85	    // out and the cache re-check is still empty, the service now calls
86	    // buildPayloadFromDb() as a last resort — matching CacheLockService::rememberLocked.
87	    //
88	    // We subclass SiteCacheService to spy on buildPayloadFromDb (which would otherwise
89	    // require a real pgsql DB). The spy returns a valid payload so we can assert the
90	    // result was NOT null, proving the code did not short-circuit before reaching it.
91	    $subdomain = 'test-fallback';
92	    $key = CacheKeyGenerator::publicSitePayload($subdomain);
93	
94	    $lock = M::mock(Lock::class);
95	    $lock->shouldReceive('block')->with(5)->once()->andThrow(new LockTimeoutException);
96	
97	    // Both reads return null: initial miss and re-check after timeout.
98	    Cache::shouldReceive('get')->with($key)->twice()->andReturn(null, null);
99	    Cache::shouldReceive('lock')->with('site:fill:'.$subdomain, 10)->once()->andReturn($lock);
100	
101	    $computeReached = false;
102	    $fakePayload = minimalCachedPayload();
103	
104	    // Anonymous subclass stubs buildPayloadFromDb so the test does not need a real DB.
105	    $service = new class(new CacheLockService, $fakePayload, $computeReached) extends SiteCacheService
106	    {
107	        public function __construct(
108	            CacheLockService $lock,
109	            private array $fakePayload,
110	            public bool &$computeReached,
111	        ) {
112	            parent::__construct($lock);
113	        }
114	
115	        protected function buildPayloadFromDb(string $subdomain, string $key): ?array
116	        {
117	            $this->computeReached = true;
118	
119	            return $this->fakePayload;
120	        }
121	    };
122	
123	    $result = $service->getPublicSitePayload($subdomain);
124	
125	    expect($computeReached)->toBeTrue()
126	        ->and($result)->toBe($fakePayload);
127	});
